package com.cpf.batch.scheduler;
import com.cpf.common.calendar.CmnBusinessCalendar; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.scheduling.support.CronExpression; import org.springframework.stereotype.Component; import org.springframework.transaction.PlatformTransactionManager; import org.springframework.transaction.support.TransactionTemplate; import java.sql.Timestamp; import java.time.*; import java.util.*;
@Component public class SchedulerDispatchService { private final SchedulerCoordinator coordinator;private final JdbcTemplate jdbc;private final CmnBusinessCalendar calendar;private final TransactionTemplate tx;public SchedulerDispatchService(SchedulerCoordinator c,JdbcTemplate j,CmnBusinessCalendar cal,PlatformTransactionManager tm){coordinator=c;jdbc=j;calendar=cal;tx=new TransactionTemplate(tm);} @Scheduled(fixedDelayString="${cpf.batch.scheduler.dispatch-ms:1000}") public void dispatchDue(){long f=coordinator.fencingToken();if(f<=0)return;coordinator.assertLeader(f);List<Map<String,Object>> due=jdbc.queryForList("SELECT s.schedule_id,s.job_id,s.cron_expression,s.calendar_id,s.business_day_only_yn,s.holiday_policy,s.timezone,s.next_fire_at FROM bat_schedule s JOIN bat_job j ON j.job_id=s.job_id WHERE s.enabled_yn='Y' AND j.use_yn='Y' AND (s.next_fire_at IS NULL OR s.next_fire_at<=CURRENT_TIMESTAMP) ORDER BY COALESCE(s.next_fire_at,CURRENT_TIMESTAMP),s.schedule_id LIMIT 100");for(var row:due)tx.executeWithoutResult(x->fire(row,f));} private void fire(Map<String,Object> row,long f){coordinator.assertLeader(f);String sid=String.valueOf(row.get("schedule_id")),job=String.valueOf(row.get("job_id"));ZoneId zone=ZoneId.of(Objects.toString(row.get("timezone"),"Asia/Seoul"));ZonedDateTime fire=row.get("next_fire_at")==null?ZonedDateTime.now(zone):((Timestamp)row.get("next_fire_at")).toInstant().atZone(zone);LocalDate bd=fire.toLocalDate();if("Y".equals(row.get("business_day_only_yn"))&&!calendar.isBusinessDay(Objects.toString(row.get("calendar_id"),"DEFAULT"),bd)){if("NEXT_BUSINESS_DAY".equalsIgnoreCase(Objects.toString(row.get("holiday_policy"),"SKIP")))bd=calendar.nextBusinessDay(Objects.toString(row.get("calendar_id"),"DEFAULT"),bd,1);else{next(row,fire);return;}}int inserted=jdbc.update("INSERT IGNORE INTO bat_schedule_trigger(schedule_id,scheduled_fire_at,fencing_token,trigger_status,created_at) VALUES(?,?,?,'CREATED',CURRENT_TIMESTAMP(6))",sid,Timestamp.from(fire.toInstant()),f);if(inserted==1){jdbc.update("INSERT INTO bat_execution(job_id,schedule_id,job_parameters,execution_status,business_date,requested_by,created_by) VALUES(?,?,'{}','READY',?,'SCHEDULER','SCHEDULER')",job,sid,java.sql.Date.valueOf(bd));Long exec=jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);jdbc.update("UPDATE bat_schedule_trigger SET execution_id=?,trigger_status='DISPATCHED' WHERE schedule_id=? AND scheduled_fire_at=?",exec,sid,Timestamp.from(fire.toInstant()));}next(row,fire);} private void next(Map<String,Object> row,ZonedDateTime from){LocalDateTime n=CronExpression.parse(String.valueOf(row.get("cron_expression"))).next(from.toLocalDateTime());if(n==null)throw new IllegalStateException("No next cron fire");ZoneId z=ZoneId.of(Objects.toString(row.get("timezone"),"Asia/Seoul"));jdbc.update("UPDATE bat_schedule SET last_fire_at=?,next_fire_at=?,updated_at=CURRENT_TIMESTAMP WHERE schedule_id=?",Timestamp.from(from.toInstant()),Timestamp.from(n.atZone(z).toInstant()),row.get("schedule_id"));} }
